<script>
(()=>{const endpoint=@json(route('ccs.customer-access.serial-preview.data')),find=@json(route('ccs.customer-access.serial-preview.find-customers')),base=@json(url(request()->is('t','t/*')?'/t/customers':'/ccs/customers')),warranties=@json(route('ccs.warranties')),customerSearch=@json(route('ccs.customer-access.serial-preview.customer-search')),serialList=@json(route('ccs.customer-access.serial-preview.customer-serials')),t={{ Illuminate\Support\Js::from($previewText) }};
const $=id=>document.getElementById(id);let version=0,selected='',lastQuery=null,serialVersion=0,serialPage=1,searchVersion=0;function node(tag,value){const e=document.createElement(tag);e.textContent=value;return e}function reset(){++version;lastQuery=null;for(const id of ['previewRecords','previewWarranties','previewOtherWarranties','previewMatches'])$(id).replaceChildren();$('previewPrevious').hidden=true;$('previewNext').hidden=true;$('customerActions').hidden=true;selected='';$('previewStatus').textContent=''}
function choose(c){++version;lastQuery=null;for(const id of ['previewRecords','previewWarranties','previewOtherWarranties'])$(id).replaceChildren();$('previewPrevious').hidden=true;$('previewNext').hidden=true;selected=String(c.id);$('previewMatches').replaceChildren();$('selectedCustomerName').textContent=[c.name,c.customer_code,c.phone].filter(Boolean).join(' · ');$('allCustomerSerials').href=base+'/'+encodeURIComponent(c.id)+'/serial-records';$('customerWarrantyCards').href=warranties+'?'+new URLSearchParams({customer_id:c.id});$('customerActions').hidden=false;loadSerials(1);if($('previewSerial').value.trim())load(1)}
async function load(page){const current=++version;const serial=$('previewSerial').value.trim();if(!selected||!serial)return;const query={customer_id:selected,serial_number:serial,page};$('previewStatus').textContent=t.loading;try{const response=await fetch(endpoint+'?'+new URLSearchParams(query),{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});const body=await response.json();if(current!==version)return;if(!response.ok)throw Error(t.error);lastQuery=query;const records=$('previewRecords');records.replaceChildren();for(const record of body.data){const card=node('article','');card.append(node('strong',record.vehicle.registration_number+' · '+record.vehicle.make+' '+record.vehicle.model),node('p',record.part.description+' · '+record.part.serial_number),node('p',record.job_number+' · '+(record.recorded_at||'—')));if(record.source==='battery_module')card.append(node('p',t.voltage+': '+(record.part.voltage??t.unmeasured)));records.append(card)}if(!body.data.length)records.append(node('p',t.none));const exact=$('previewWarranties'),other=$('previewOtherWarranties');exact.replaceChildren();other.replaceChildren();for(const w of body.warranties){const card=node('article','');card.append(node('strong',w.name+' · '+(w.covered_serial||'—')),node('p',w.job_number+' · '+w.starts_on+' → '+(w.expires_on||'—')));if(w.card_status)card.append(node('p',w.card_status.card_number+' · '+w.card_status.state+' · '+(w.card_status.remaining_days===null?'—':w.card_status.remaining_days+' '+t.days)));if(w.terms)card.append(node('p',typeof w.terms==='string'?w.terms:JSON.stringify(w.terms)));(w.covered_serial&&w.covered_serial.trim().toLocaleLowerCase()===serial.toLocaleLowerCase()?exact:other).append(card)}if(!exact.children.length)exact.append(node('p',t.noWarranty));if(!other.children.length)other.append(node('p',t.other));$('previewStatus').textContent=body.meta.total+' · '+body.meta.current_page+' / '+body.meta.last_page;$('previewPrevious').hidden=page<=1;$('previewNext').hidden=page>=body.meta.last_page}catch(e){if(current===version)$('previewStatus').textContent=t.error}}
async function loadSerials(page){const id=selected,current=++serialVersion;serialPage=page;$('customerSerialList').replaceChildren();$('customerSerialStatus').textContent=t.loading;$('serialListPrevious').hidden=true;$('serialListNext').hidden=true;try{const response=await fetch(serialList+'?'+new URLSearchParams({customer_id:id,page}),{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw Error();const body=await response.json();if(current!==serialVersion||id!==selected)return;$('customerSerialStatus').textContent=body.data.length?body.total+' · '+body.current_page+' / '+body.last_page:t.noSerials;for(const row of body.data){const b=node('button',row.serial_number);b.type='button';b.className='secondary';b.addEventListener('click',()=>{$('previewSerial').value=row.serial_number;load(1)});$('customerSerialList').append(b)}$('serialListPrevious').hidden=page<=1;$('serialListNext').hidden=page>=body.last_page}catch(e){if(current===serialVersion)$('customerSerialStatus').textContent=t.error}}
$('serialListPrevious').onclick=()=>loadSerials(serialPage-1);$('serialListNext').onclick=()=>loadSerials(serialPage+1);$('closeCustomerMatches').onclick=()=>$('customerMatchDialog').close();
async function searchCustomer(){const q=$('customerLookup').value.trim(),current=++searchVersion;if(q.length<2){$('customerLookupStatus').textContent=t.noCustomer;return}$('customerLookupStatus').textContent=t.loading;try{const response=await fetch(customerSearch+'?'+new URLSearchParams({q}),{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw Error();const body=await response.json();if(current!==searchVersion)return;$('customerLookupStatus').textContent=body.data.length?(body.has_more?t.more:''):t.noCustomer;if(body.data.length===1&&!body.has_more){$('previewSerial').value='';choose(body.data[0]);return}if(!body.data.length)return;const list=$('customerMatchList');list.replaceChildren();for(const c of body.data){const b=node('button',[c.name,c.customer_code,c.phone,c.nic,...(c.plates||[])].filter(Boolean).join(' · '));b.type='button';b.addEventListener('click',()=>{$('customerMatchDialog').close();$('previewSerial').value='';choose(c)});list.append(b)}if(!$('customerMatchDialog').open)$('customerMatchDialog').showModal()}catch(e){if(current===searchVersion)$('customerLookupStatus').textContent=t.error}}
$('customerLookupButton').onclick=searchCustomer;$('customerLookup').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchCustomer()}});$('customerLookup').addEventListener('input',()=>{++searchVersion;$('customerLookupStatus').textContent=''});
$('serialPreviewForm').addEventListener('submit',async e=>{e.preventDefault();reset();const current=++version,serial=$('previewSerial').value.trim();if(!serial)return;$('previewStatus').textContent=t.loading;try{const response=await fetch(find+'?'+new URLSearchParams({serial_number:serial}),{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});const body=await response.json();if(current!==version)return;if(!response.ok)throw Error();if(body.data.length===1&&!body.has_more){choose(body.data[0]);return}$('previewStatus').textContent=body.data.length?(body.has_more?t.more:t.choose):t.none;for(const c of body.data){const button=node('button',[c.name,c.customer_code,c.phone].filter(Boolean).join(' · '));button.type='button';button.addEventListener('click',()=>choose(c));$('previewMatches').append(button)}}catch(e){if(current===version)$('previewStatus').textContent=t.error}});
$('previewSerial').addEventListener('input',reset);$('customerFilter').addEventListener('input',()=>{const q=$('customerFilter').value.toLocaleLowerCase();for(const o of $('previewCustomer').options)o.hidden=!o.textContent.toLocaleLowerCase().includes(q)});$('selectPreviewCustomer').onclick=()=>{const o=$('previewCustomer').selectedOptions[0];if(o)choose({id:o.value,name:o.textContent})};$('previewPrevious').onclick=()=>{if(lastQuery)load(Number(lastQuery.page)-1)};$('previewNext').onclick=()=>{if(lastQuery)load(Number(lastQuery.page)+1)};
})();
</script>
